<template>
 <section class="matching" aria-label="Find matching openings">
  <div class="search-heading"><div><p class="eyebrow">Search provider availability</p><h3>Find the right opening</h3></div><span class="search-note">Ask naturally, then narrow your results</span></div>
  <form @submit.prevent="ask()"><label>{{result?'Follow up on this search':'Day, time, or client needs'}}<input v-model="question" :placeholder="result?'For example: Which of those see kids?':'Who has availability Thursdays at 7 AM?'" required/></label><button class="primary" :disabled="busy">{{busy?'Checking calendars…':result?'Ask follow-up':'Find openings'}}</button><button type="button" class="secondary" @click="reset" :disabled="busy">New search</button></form>
  <details class="client-match"><summary>Match a submitted client’s preferences</summary><form @submit.prevent="findClients"><label>Client name or initials<input v-model="clientQuery" minlength="2" required/></label><button class="secondary" :disabled="busy">Find client</button></form><ul><li v-for="c in clients" :key="c.id">{{c.full_name||c.initials||('Client #'+c.id)}} <button class="secondary" :disabled="busy" @click="ask(`Match client #${c.id} preferences to provider availability`)">Find matching providers</button></li></ul><p>Uses their saved day, time, format, location, and age preferences. Missing details are listed for review.</p></details>
  <p v-if="error" role="alert">{{error}}</p>
  <div v-if="result&&!result.needsClarification" class="answer structured-answer" aria-live="polite">
   <div class="result-heading"><div><p class="asked">You asked: {{lastQuestion}}</p><h4>{{result.providers.length}} {{result.providers.length===1?'provider matches':'providers match'}}</h4><p>{{windowLabel}} · {{result.timeZone}}</p></div><div class="filter-tags"><span v-for="label in filterLabels" :key="label">{{label}}</span></div></div>
   <article v-for="person in result.providers" :key="person.providerId" class="match-row"><div class="match-person"><img v-if="photo(person)&&!failedPhotos.has(person.providerId)" :src="photo(person)" alt="" @error="failedPhotos.add(person.providerId)"/><span v-else class="avatar" aria-hidden="true">{{initials(person.name)}}</span><div><h5>{{person.name}}</h5><p>{{person.title||'Provider'}}</p><small v-if="result.filters.children||result.filters.ageBucket">{{person.ages?.join(' · ')}}</small></div></div><div class="match-times"><div v-for="group in groups(person)" :key="group.date" class="match-day"><strong>{{date(group.startAt)}}</strong><div><span v-for="(slot,i) in group.slots" :key="i" class="time-chip">{{time(slot.startAt)}} · {{slot.format==='VIRTUAL'?'Virtual':slot.buildingName||'In person'}} <small>{{frequency(slot)}}</small></span></div></div><small v-if="person.totalSlots>person.slots.length">{{person.totalSlots-person.slots.length}} more matching times</small><p v-if="person.calendarWarnings?.length" class="warning">Calendar check incomplete — confirm before booking.</p><p v-for="item in person.review||[]" :key="item" class="review">{{item}}</p></div><div class="match-actions"><button class="secondary" @click="$emit('manage',{providerId:person.providerId,tab:'openings'})">View openings</button><button v-if="canEditPreferences" class="text-button" @click="$emit('manage',{providerId:person.providerId,tab:'preferences'})">Edit preferences →</button></div></article>
   <p v-if="!result.providers.length" class="empty">No confirmed matches for these criteria. Try another time or format.</p>
   <details v-if="result.failedProviderIds?.length||result.unverified?.length||result.unknownAgeProviderCount" class="verification"><summary>{{result.failedProviderIds?.length?`${result.failedProviderIds.length} providers need a calendar check`:'Some preferences need review'}}</summary><p v-if="result.failedProviderIds?.length">These providers could not be fully checked. They have not been marked unavailable: {{failedNames}}.</p><p v-if="result.unknownAgeProviderCount">{{result.unknownAgeProviderCount}} providers have no recorded age range and are not counted as age matches.</p><ul><li v-for="item in result.unverified||[]" :key="item">{{item}}</li></ul></details>
   <p class="result-footnote">Published openings after calendar checks. Confirm future dates and client fit when booking. <span v-if="result.checkedAt">Checked {{time(result.checkedAt)}}.</span></p>
  </div>
  <div v-else-if="answer" class="answer fallback" role="status">{{answer}}</div>
 </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import api from '../../services/api';
import {availabilityDayGroups} from '../../utils/availabilityDayGroups';
const props=defineProps({agencyId:{type:Number,required:true},providers:{type:Array,default:()=>[]},canEditPreferences:{type:Boolean,default:true}});
defineEmits(['manage']);
const availabilityQueries=ref([]),result=ref(null),lastQuestion=ref(''),failedPhotos=ref(new Set());
const question=ref(''),history=ref([]),answer=ref(''),busy=ref(false),error=ref(''),clientQuery=ref(''),clients=ref([]);
const tz=computed(()=>result.value?.timeZone||'America/Denver');
const date=s=>new Date(s).toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:tz.value});
const time=s=>new Date(s).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:tz.value});
const wallTime=t=>{if(!t)return '';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;};
const windowLabel=computed(()=>{const f=result.value?.filters||{};const day=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:'UTC'});return `${day(f.dateFrom)}${f.dateTo!==f.dateFrom?' – '+day(f.dateTo):''}${f.exactTime?' at '+wallTime(f.exactTime):f.timeFrom||f.timeTo?' · '+(wallTime(f.timeFrom)||'Any start')+'–'+(wallTime(f.timeTo)||'Any end'):''}`;});
const filterLabels=computed(()=>{const f=result.value?.filters||{};return [f.modality==='VIRTUAL'?'Virtual':f.modality==='IN_PERSON'?'In person':'Any format',f.care?f.care[0]+f.care.slice(1).toLowerCase():null,f.children?'Children / teens':f.ageBucket,f.specialty,f.location,f.frequency?frequency({frequency:f.frequency}):null].filter(Boolean);});
const groups=person=>availabilityDayGroups(person.slots,tz.value);
const initials=name=>String(name).split(' ').map(s=>s[0]).slice(0,2).join('');
const photo=person=>person.profilePhotoUrl||props.providers.find(p=>Number(p.id)===Number(person.providerId))?.profilePhotoUrl;
const frequency=slot=>({WEEKLY:'Weekly',BIWEEKLY:'Every 2 weeks',EVERY_3_WEEKS:'Every 3 weeks',EVERY_4_WEEKS:'Every 4 weeks',ONCE:slot.purpose==='MEETING'?'One-time meeting':'Single intake'}[slot.frequency]||slot.frequency||'');
const failedNames=computed(()=>(result.value?.failedProviderIds||[]).map(id=>{const p=props.providers.find(p=>Number(p.id)===Number(id));return p?[p.first_name,p.last_name].filter(Boolean).join(' '):`Provider #${id}`;}).join(', '));
let generation=0;
function reset(){generation++;availabilityQueries.value=[];question.value='';history.value=[];answer.value='';result.value=null;lastQuestion.value='';error.value='';clients.value=[];}
async function findClients(){busy.value=true;error.value='';const g=generation;try{const {data}=await api.get('/clients',{params:{agency_id:props.agencyId,search:clientQuery.value,page:1,per_page:10}});if(g===generation)clients.value=Array.isArray(data)?data:data.items||[];}catch(e){if(g===generation)error.value=e.response?.data?.error?.message||'Could not find clients.';}finally{if(g===generation)busy.value=false;}}
async function ask(text){const q=typeof text==='string'?text:question.value;if(!q.trim())return;const g=generation;busy.value=true;error.value='';try{const {data}=await api.post('/agents/assist',{prompt:q,history:history.value.slice(-8),context:{agencyId:props.agencyId,answerOnly:true,availabilityQueries:availabilityQueries.value}},{timeout:180000});if(g!==generation)return;availabilityQueries.value=data.availabilityQueries||[];answer.value=data.assistantText||'Could not complete this search.';result.value=data.toolResults?.find(r=>r.ok&&r.tool==='findProviderAvailability')?.result||null;lastQuestion.value=q;history.value.push({role:'user',text:q},{role:'assistant',text:answer.value});question.value='';}catch(e){if(g===generation)error.value=e.response?.data?.error?.message||'Could not check availability. Please retry.';}finally{if(g===generation)busy.value=false;}}
watch(()=>props.agencyId,()=>{reset();busy.value=false;});
</script>
<style scoped>
.matching{padding:24px;background:#f6faf8;border:1px solid #d4e3da;border-radius:14px;margin:22px 0;color:#233f35}.search-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#608170;margin:0 0 7px}.matching h3{font-size:21px;margin:0;color:inherit}.search-note{font-size:12px;color:#708576}.matching form{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:20px 0 14px}.matching label{display:grid;gap:7px;flex:1;min-width:180px;font-size:12px;font-weight:600}.matching input{padding:12px;border:1px solid #c3d6ca;border-radius:8px;font:inherit;font-weight:400;font-size:14px;width:100%;box-sizing:border-box;background:white;color:inherit}.matching button{padding:11px 15px;border-radius:8px;border:1px solid #bed1c4;cursor:pointer;font:inherit;font-size:12px;font-weight:600;color:#245b44;background:white}.matching .primary{background:#176448;color:white;border-color:#176448}.matching button:disabled{opacity:.6}.matching .text-button{border:0;background:none;padding:8px 0}.client-match{font-size:12px;color:#587363}.matching summary{cursor:pointer}.answer{margin-top:22px}.fallback{white-space:pre-wrap;line-height:1.6}.result-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-bottom:18px}.asked{font-size:12px;color:#6a7d71;margin:0 0 7px}.result-heading h4{margin:0;font-size:19px}.result-heading p:not(.asked){font-size:13px;margin:7px 0 0}.filter-tags{display:flex;flex-wrap:wrap;gap:6px}.filter-tags span{font-size:11px;background:#e6f0ea;padding:6px 9px;border-radius:20px;white-space:nowrap}.match-row{display:grid;grid-template-columns:minmax(170px,1fr) 2fr auto;gap:24px;padding:22px 0;border-top:1px solid #dce7df;align-items:start}.match-person{display:flex;gap:12px;align-items:center}.match-person img,.avatar{width:52px;height:62px;object-fit:cover;border-radius:10px;flex:none}.avatar{display:grid;place-items:center;background:#e4eee7;color:#416e55;font-weight:700}.match-person h5{font-size:16px;margin:0 0 5px}.match-person p,.match-person small{font-size:12px;color:#6c7d72;margin:0}.match-day strong{font-size:12px;font-weight:600}.match-day{margin-bottom:8px}.match-day>div{display:flex;flex-wrap:wrap;gap:6px;margin-top:7px}.time-chip{display:inline-flex;gap:8px;align-items:center;background:white;border:1px solid #d1e1d7;border-radius:7px;padding:8px 10px;font-size:13px}.time-chip small{font-size:10px;color:#638170}.match-actions{display:grid;gap:6px;align-content:start}.result-footnote{font-size:11px;color:#748477;line-height:1.5}.verification{font-size:12px;padding:12px 15px;border:1px solid #e5d9b8;border-radius:8px;background:#fffbf0;color:#816126;margin:14px 0}.verification p{line-height:1.5}.warning,.review{font-size:12px;color:#87622e}.empty{font-size:14px}.matching [role=alert]{color:#a42030}.matching :focus-visible{outline:3px solid #c99718;outline-offset:2px}@media(max-width:750px){.matching{padding:18px}.search-note{display:none}.match-row{grid-template-columns:1fr;gap:14px}.match-actions{display:flex;gap:14px}.result-heading{align-items:start;flex-direction:column}.matching form>label{flex-basis:100%}.time-chip{flex-wrap:wrap}.search-heading h3{font-size:19px}}
</style>
